// Normalise website events. Roast requests carry `mode`; other events carry `type`.
// SECURITY: set EXPECTED to the bearer token once N8N_ROAST_TOKEN is chosen.
const EXPECTED = '';
const req = $input.first().json;
const headers = req.headers || {};
if (EXPECTED) {
  const auth = String(headers.authorization || '');
  if (auth !== `Bearer ${EXPECTED}`) {
    return [{ json: { branch: 'health', payload: { unauthorized: true } } }];
  }
}
const body = req.body || {};
let branch = 'health';
if (body.mode) branch = 'roast';
else if (body.type === 'lead') branch = 'lead';
else if (body.type === 'metrics') branch = 'metrics';
return [{ json: { branch, payload: body } }];

// Vira, the StayEdge roast persona. HONESTY LAWS: only claims verifiable from
// the provided input; never invent facts, prices, ratings or local statistics;
// low input = low confidence + needsGuided. Registers: roast (cheeky, never
// cruel), diagnose (boardroom), growth (opportunity-first).
const p = $input.first().json.payload;
const mode = ['roast','diagnose','growth'].includes(p.mode) ? p.mode : 'roast';
const instructions = `You are Vira, StayEdge's Airbnb growth consultant (sharp operator, not loud guru; no exclamation marks; no hype).
Analyse ONLY what the input actually contains. NEVER invent facts, numbers, ratings, competitors or local statistics. If the input is too thin to say anything specific, return needsGuided=true with empty issues.
Register: ${mode === 'roast' ? 'funny, cheeky, memorable — roast the LISTING, never the person' : mode === 'diagnose' ? 'professional, precise, data-led, boardroom-safe' : 'positive coaching, opportunity-first, encouraging'}.
Rules for the output contract:
- score: 20-98 integer reflecting listing quality from the evidence given, or null if needsGuided.
- benchmark: always 85.
- issues: up to 6 findings, each {tag: short label, line: one specific sentence tied to actual input evidence}. First 3 are shown free.
- positive: exactly one GENUINE strength from the input (the hope beat), or a warm true generic if nothing else ({tag:'Foundation', line:'...'}).
- moreCount: issues.length minus 3, minimum 0.
- confidence: high only if title AND price AND description provided; medium if some; low if minimal.
- needsGuided: true only when there is nothing concrete to analyse.
- note: honest caveat when confidence is not high.`;
const schemaExample = JSON.stringify({ score: 62, benchmark: 85, issues: [{ tag: 'Title', line: 'Example finding tied to evidence.' }], positive: { tag: 'Location', line: 'Example genuine strength.', positive: true }, moreCount: 1, confidence: 'medium', needsGuided: false, note: 'Based on what you shared so far.' });
return [{ json: { instructions, content: JSON.stringify(p), schemaExample, payload: p } }];

// Clamp the model output into the website contract. Any failure degrades to
// needsGuided — the website then uses its own heuristic; the visitor never errors.
const r = $input.first().json;
const fallback = { score: null, benchmark: 85, issues: [], positive: null, moreCount: 0, confidence: 'low', needsGuided: true, note: 'Give me a little to work with and I will be specific.' };
if (!r.ok || !r.json) return [{ json: fallback }];
const j = r.json;
const finding = (f) => f && typeof f.tag === 'string' && typeof f.line === 'string' ? { tag: f.tag.slice(0, 60), line: f.line.slice(0, 600), ...(f.positive ? { positive: true } : {}) } : null;
const issues = Array.isArray(j.issues) ? j.issues.map(finding).filter(Boolean).slice(0, 20) : [];
const score = typeof j.score === 'number' ? Math.max(0, Math.min(100, Math.round(j.score))) : null;
const confidence = ['high','medium','low'].includes(j.confidence) ? j.confidence : 'low';
const out = {
  score,
  benchmark: 85,
  issues,
  positive: finding(j.positive),
  moreCount: Math.max(0, issues.length - 3),
  confidence,
  needsGuided: Boolean(j.needsGuided) || score === null,
  ...(typeof j.note === 'string' ? { note: j.note.slice(0, 400) } : {})
};
return [{ json: out }];
